# CELL 8: RETIRED OVERRIDE, AND THE SHADOWING CHECK   (Eir 2.0.13)
# ============================================================================
# This cell used to redefine geometry_plausible(), shadowing the definition in
# CELL 7. The override is now IN CELL 7, beside its only caller, and this cell
# defines nothing. What remains is the check that no cell redefines it again.
#
# WHAT THE OVERRIDE DID
#
#   It made the radius-ratio verdict advisory (None, 'not judged') for large
#   weakly bonded cations and for any site with CN >= 8 - but only when the
#   ratio FAILED. A passing site still passed, so the test was one-sided and
#   such a cation could never fail the radii screen.
#
#   It was written when the radius lookup was fixed at six-coordinate, which
#   genuinely did penalise dispersed high-coordination cations. Since v1.8.9
#   the radius comes from get_ionic_radius_fractional() at the site's own
#   valence and coordination number. Over 1886 sites in the 934-structure ICSD
#   perovskite set the two ratio distributions are then indistinguishable
#   (median 0.922 against 0.974, 1st percentile 0.765 against 0.763, 3.1%
#   against 2.9% below the 0.85 threshold), so the concession had nothing left
#   to correct for.
#
#   Meanwhile it was suppressing five entries whose contacts are impossible:
#   LaCrO3 220506 at ratio 0.415 with a bond valence sum 769% above its formal
#   valence, YVO3 121777 at 0.610, NdFeO3 74087 at 0.632, CaTiO3 132626 at
#   0.680 and La0.8MnO2.8 33482 at 0.682.
#
# v2.0.13: the concession was gated on a 25-element list called A_SITE_ELEMENTS
# plus a coordination threshold. That is perovskite vocabulary in a tool that
# also runs on pyrochlores, spinels and rock salts, none of which has an A
# site. It is now gated on WEAK_CATION_LEWIS_MAX - valence divided by
# coordination number - which is structure-agnostic, needs no list, and is the
# same measure that sets the bond-valence shell boundary.
#
# To restore a concession, set WEAK_CATION_ADVISORY_FLOOR in CELL 7 (0.80 is
# the defensible value; it leaves all five entries above failing). Do not
# reinstate a redefinition here: two definitions of one function in a notebook
# is how the behaviour in force stopped being the behaviour anyone was reading.
# ============================================================================


def _eir_check_no_shadowing(verbose=True):
    """
    Confirm that the functions this notebook relies on are defined once.

    A redefinition later in a notebook silently wins and nothing announces it.
    That is how the override went unnoticed: CELL 7 was read, CELL 8 was what
    ran.

    This complements the structural self-check in CELL 1c, which scans the
    saved SOURCE for duplicate definitions. This one inspects the LIVE object,
    so it also catches a redefinition made interactively after the notebook
    was saved.
    """
    expected_owner = {
        'geometry_plausible': 'CELL 7',
        'add_coordination_quality': 'CELL 7',
        'cn_fault': 'CELL 2',
        'guarded_shell_cn': 'CELL 2',
        'core_radii_ratio': 'CELL 2',
        'calculate_anion_bvs': 'CELL 3',
        'summarise_anion_bvs': 'CELL 3',
    }
    g = globals()
    missing = [f'{n} ({o})' for n, o in expected_owner.items() if g.get(n) is None]
    if missing:
        raise NameError(
            'Not defined: ' + ', '.join(missing) +
            '. Run the owning cells before this one.')

    # The specific regression this cell exists to prevent. Checked by an
    # attribute set in CELL 7 rather than by reading the source: an attribute
    # survives exec, import and %run, whereas inspect.getsource() cannot always
    # resolve a function defined in a notebook cell, and a check that cannot
    # see its own evidence would raise a false alarm.
    fn = g['geometry_plausible']
    owner = getattr(fn, '_eir_cell', None)
    if owner != 'CELL 7':
        raise AssertionError(
            'geometry_plausible() in force is not the CELL 7 version '
            f'(owner tag: {owner!r}). Another cell is redefining it. Find and '
            'remove that definition: while it stands, radius-ratio failures on '
            'weakly bonded cations are suppressed and the geometry screen '
            'reports a pass rate it has not measured.')

    floor = g.get('WEAK_CATION_ADVISORY_FLOOR', 'undefined')
    lmax = g.get('WEAK_CATION_LEWIS_MAX', 'undefined')
    if verbose:
        print('Eir 2.0.13 CELL 8: the radii-ratio override is retired; '
              'nothing is defined here.')
        print('  geometry_plausible() in force is the CELL 7 version.')
        print(f'  WEAK_CATION_ADVISORY_FLOOR = {floor}'
              + ('  (no concession; every cation is judged on the same '
                 'footing)' if floor is None else
                 f'  (advisory between this and the threshold, for cations '
                 f'with valence/CN <= {lmax})'))
        print(f'  {len(expected_owner)} shared functions present and owned '
              f'as expected.')
    return True


_eir_check_no_shadowing()
